static int valid(const struct file*f){static const uint8_t p[]="seed/";uint32_t i,s=sizeof(p)-1u,n=f->path_length;if(n<=s)return 0;for(i=0;i<s;++i)if(f->path[i]!=p[i])return 0;for(i=0;i<n;++i)if(!f->path[i])return 0;for(i=s;i<=n;++i)if(i==n||f->path[i]=='/'){uint32_t z=i-s;if(!z||(z==1&&f->path[s]=='.')||(z==2&&f->path[s]=='.'&&f->path[s+1u]=='.'))return 0;s=i+1u;}return 1;}int source_snapshot_measure(uint16_t*c,uint32_t*n){uint16_t q=0;uint32_t z=2;for(uint32_t i=0;i<file_count;++i){const struct file*f=&files[i];if(!valid(f))continue;uint32_t x=6u+f->path_length;if(x>FRAME_MAX_PAYLOAD-z||file_size(f)>FRAME_MAX_PAYLOAD-z-x)return 0;z+=x+file_size(f);++q;}*c=q;*n=z;return 1;}void source_snapshot_write(uint16_t count){frame_write_u16(count);for(uint32_t i=0;i<file_count;++i){const struct file*f=&files[i];if(!valid(f))continue;frame_write_u16(f->path_length);serial_write_bytes(f->path,f->path_length);frame_write_u32(file_size(f));serial_write_bytes(file_content(f),file_size(f));}}
